def transform(g):
    n=len(g); P=5; B=4
    def pat(r0,c0):
        return [(r-r0,c-c0) for r in range(r0,min(r0+B,n)) for c in range(c0,min(c0+B,n)) if g[r][c]==2]
    nb=n//P+ (1 if n%P else 0)  # boxes at 0,5,...
    nb=(n+1)//P
    # shape S: pattern from the first box containing 2s whose pattern is nonempty & 'complete' (take most common nonempty pattern)
    from collections import Counter
    pats=[pat(r0*P,c0*P) for r0 in range(nb) for c0 in range(nb)]
    pats=[tuple(p) for p in pats if p]
    S=list(Counter(pats).most_common(1)[0][0])
    out=[row[:] for row in g]
    shapes=[]
    for r0 in range(nb):
        for c0 in range(nb):
            box=[(r0*P+dr,c0*P+dc) for dr,dc in S]
            has3=any(0<=r<n and 0<=c<n and out[r][c]==3 for r,c in box)
            if has3 or (r0,c0) in [(r//P,c//P) for r,c in []]:
                pass
            present=any(0<=r<n and 0<=c<n and g[r][c]==2 for r,c in box)
            if has3:
                for r in range(r0*P,min(r0*P+B,n)):
                    for c in range(c0*P,min(c0*P+B,n)):
                        out[r][c]=0
            if has3 and (r0,c0) in [(r//P,c//P) for r,c in S]:
                for r,c in box:
                    if 0<=r<n and 0<=c<n: out[r][c]=2
            if (r0,c0) in [(r//P,c//P) for r,c in S] or (present and not has3):
                shapes.append((r0,c0))
    Sset=set(S)
    for k,(r0,c0) in enumerate(shapes):
        if k<len(S):
            dr,dc=S[k]
            out[r0*P+dr][c0*P+dc]=8
    return out

